def json_safe_default(obj):
    """
    Convert NumPy/Pandas/Path objects into native JSON-safe types.
    """
    if isinstance(obj, np.generic):
        return obj.item()

    if isinstance(obj, Path):
        return str(obj)

    if isinstance(obj, (datetime.datetime, datetime.date)):
        return obj.isoformat()

    raise TypeError(
        f"Object of type {type(obj).__name__} "
        "is not JSON serializable"
    )

def atomic_json_save(data, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)

    tmp = path.with_suffix(
        path.suffix + ".tmp"
    )

    with open(
        tmp,
        "w",
        encoding="utf-8"
    ) as f:

        json.dump(
            data,
            f,
            indent=2,
            ensure_ascii=False,
            default=json_safe_default
        )

        f.flush()
        os.fsync(f.fileno())

    os.replace(
        tmp,
        path
    )

def atomic_csv_save(df, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    df.to_csv(tmp, index=False)
    os.replace(tmp, path)

def atomic_parquet_save(df, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = Path(str(path) + ".tmp.parquet")
    df.to_parquet(tmp, index=False)
    os.replace(tmp, path)

def valid_json(path):
    path = Path(path)
    if not path.exists():
        return False
    try:
        with open(path, encoding="utf-8") as f:
            json.load(f)
        return True
    except Exception:
        return False

def valid_csv(path, min_rows=1):
    path = Path(path)
    if not path.exists():
        return False
    try:
        x = pd.read_csv(path)
        return len(x) >= min_rows
    except Exception:
        return False

def valid_parquet(path, min_rows=1):
    path = Path(path)
    if not path.exists():
        return False
    try:
        x = pd.read_parquet(path)
        return len(x) >= min_rows
    except Exception:
        return False

def sha256_file(path, chunk_size=1024 * 1024):
    sha = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            b = f.read(chunk_size)
            if not b:
                break
            sha.update(b)
    return sha.hexdigest()

STATE_FILE = DIRS["state"] / f"pipeline_state_{PHASE1_ID}.json"

def load_state():
