        "gate4": "pending",
        "rq1": "pending",
        "rq2": "pending",
        "last_update": None,
    }
    atomic_json_save(state, STATE_FILE)
    return state

def set_state(key, value):
    state = load_state()
    state[key] = value
    state["last_update"] = datetime.datetime.now().isoformat()
    atomic_json_save(state, STATE_FILE)

def heartbeat(stage, **kwargs):
