def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_text(text: str) -> str:
    return sha256_bytes(
        text.encode("utf-8")
    )


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()

    with path.open("rb") as f:
        while True:
            block = f.read(1024 * 1024)

            if not block:
                break

            h.update(block)

    return h.hexdigest()


def atomic_json(path: Path, obj):
    tmp = path.with_suffix(
        path.suffix + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8"
    ) as f:
        json.dump(
            obj,
            f,
            indent=2,
            ensure_ascii=False
        )

        f.flush()
        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path
    )


def write_text_fsync(path: Path, text: str):
    with path.open(
        "w",
        encoding="utf-8"
    ) as f:
        f.write(text)

        f.flush()
        os.fsync(
            f.fileno()
        )


def cell_source(cell):
    src = cell.get(
        "source",
        ""
    )

    if isinstance(src, list):
        return "".join(src)

    return str(src)


# ============================================================
# 3. LOAD ORIGINAL NOTEBOOK
# ============================================================

with NOTEBOOK.open(
    encoding="utf-8"
) as f:
    nb = json.load(f)


cells = nb.get(
    "cells",
    []
)

code_cells = [
    (i, cell_source(cell))
    for i, cell in enumerate(cells)
    if cell.get("cell_type") == "code"
]


assert len(code_cells) > 0


print(
    "✓ Code cells loaded:",
    len(code_cells)
)

print(
    "✓ Notebook SHA256:",
    sha256_file(NOTEBOOK)
)


# ============================================================
# 4. FORENSIC CELL 60A-60E EXTRACTION
#
# Do NOT rely on broad keyword matching.
# Require explicit CELL 60A ... CELL 60E markers.
# ============================================================

marker_re = re.compile(
    r"(?im)^"
    r"[ \t]*"
    r"(?:#+[ \t]*)?"
    r"(?:\[[^\n]*\][ \t]*)?"
    r"CELL[ \t]+60([A-E])\b[^\n]*$"
)


training_marker_records = []
training_sections = {
    label: []
    for label in [
        "A",
        "B",
        "C",
        "D",
        "E",
    ]
}


for cell_index, src in code_cells:

    matches = list(
        marker_re.finditer(src)
    )

    if not matches:
        continue


    for j, match in enumerate(matches):

        label = match.group(1)

        start = match.start()

        if j + 1 < len(matches):
            end = matches[j + 1].start()
        else:
            end = len(src)

        section = src[
            start:end
        ]


        record = {
            "label":
                f"CELL 60{label}",

            "cell_index":
                int(cell_index),

            "section_start_char":
                int(start),

            "section_end_char":
                int(end),

            "section_chars":
                int(len(section)),

            "section_sha256":
                sha256_text(section),

            "full_cell_sha256":
                sha256_text(src),

            "marker_line":
                match.group(0).strip(),
        }


        training_marker_records.append(
            record
        )

        training_sections[
            label
        ].append(
            {
                **record,
                "source":
                    section,
                "full_cell_source":
                    src,
            }
        )


# Require all five explicit labels.
for label in [
    "A",
    "B",
    "C",
    "D",
    "E",
]:

    assert len(
        training_sections[label]
    ) >= 1, (
        f"Explicit CELL 60{label} marker not found."
    )


print(
    "✓ Explicit Cell 60A-60E markers verified."
)


# ============================================================
# 5. SELECT AUTHORITATIVE MARKER OCCURRENCE
#
# If duplicate marker occurrences exist, choose the longest
# marker-delimited section, while preserving all candidates
# in the manifest.
# ============================================================

selected_training = {}


for label in [
    "A",
    "B",
    "C",
    "D",
    "E",
]:

    candidates = sorted(
        training_sections[label],
        key=lambda x: (
            x["section_chars"],
            -x["cell_index"],
        ),
        reverse=True,
    )

    selected_training[
        label
    ] = candidates[0]


# Cell 60A and 60B may legitimately share one notebook cell.
# What matters is that explicit marker-delimited source
