if (
    selected_training["A"]["cell_index"]
    ==
    selected_training["B"]["cell_index"]
):

    assert (
        selected_training["A"][
            "section_start_char"
        ]
        !=
        selected_training["B"][
            "section_start_char"
        ]
    ), (
        "60A and 60B point to the same exact marker span."
