# ============================================================
# 7. FIND TRUE row_id / duplicate_group_id CONSTRUCTION CELLS
#
# Broad keyword count is NOT accepted.
# We look for actual assignment syntax.
# ============================================================

TARGET_COLUMNS = {
    "row_id",
    "duplicate_group_id",
}


def subtree_mentions_string(
    node,
    target_name
):

    for child in ast.walk(node):

        if (
            isinstance(
                child,
                ast.Constant
            )
            and
            child.value
            ==
            target_name
        ):
            return True

        if (
            isinstance(
                child,
                ast.Name
            )
            and
            child.id
            ==
            target_name
        ):
            return True

    return False


def assignment_targets(node):

    if isinstance(
        node,
        ast.Assign
    ):
        return node.targets

    if isinstance(
        node,
        ast.AnnAssign
    ):
        return [
            node.target
        ]

    if isinstance(
        node,
        ast.AugAssign
    ):
        return [
            node.target
        ]

    return []


def assignment_evidence(
    src
):

    evidence = {
        "row_id": [],
        "duplicate_group_id": [],
    }


    try:
        tree = ast.parse(
            src
        )
    except SyntaxError:
        tree = None


    if tree is not None:

        for node in ast.walk(
            tree
        ):

            if isinstance(
                node,
                (
                    ast.Assign,
                    ast.AnnAssign,
                    ast.AugAssign,
                )
            ):

                targets = assignment_targets(
                    node
                )

                for target_name in TARGET_COLUMNS:

                    if any(
                        subtree_mentions_string(
                            target,
                            target_name
                        )
                        for target
                        in targets
                    ):

                        evidence[
                            target_name
                        ].append(
                            {
                                "lineno":
                                    getattr(
                                        node,
                                        "lineno",
                                        None
                                    ),

                                "type":
                                    type(node).__name__,
                            }
                        )


            # DataFrame.assign(row_id=..., duplicate_group_id=...)
            if isinstance(
                node,
                ast.Call
            ):

                for kw in node.keywords:

                    if (
                        kw.arg
                        in TARGET_COLUMNS
                    ):

                        evidence[
                            kw.arg
                        ].append(
                            {
                                "lineno":
                                    getattr(
                                        node,
                                        "lineno",
                                        None
                                    ),

                                "type":
                                    "DataFrame.assign keyword",
                            }
                        )


    # Conservative fallback for notebook code that cannot
    # be parsed because it contains magics.
    for target_name in TARGET_COLUMNS:

        patterns = [
            rf"""[\[\(]\s*["']{re.escape(target_name)}["']\s*[\]\)]\s*=""",
            rf"""\.assign\s*\([^)]*\b{re.escape(target_name)}\s*=""",
            rf"""\b{re.escape(target_name)}\s*=""",
        ]

        if (
            not evidence[target_name]
            and
            any(
                re.search(
                    p,
                    src,
                    flags=re.S
                )
                for p in patterns
            )
        ):

            evidence[
                target_name
            ].append(
                {
                    "lineno":
                        None,

                    "type":
                        "regex_assignment_fallback",
                }
            )


    return evidence


id_assignment_cells = []


for cell_index, src in code_cells:

    evidence = assignment_evidence(
        src
    )

    if (
        evidence["row_id"]
        or
        evidence["duplicate_group_id"]
    ):

        id_assignment_cells.append(
            {
                "cell_index":
                    int(cell_index),

                "row_id_assignment":
                    bool(
                        evidence[
                            "row_id"
                        ]
                    ),

                "duplicate_group_id_assignment":
                    bool(
                        evidence[
                            "duplicate_group_id"
                        ]
                    ),

                "evidence":
                    evidence,

                "source_sha256":
                    sha256_text(src),

                "source":
                    src,
            }
        )


assert any(
    x["row_id_assignment"]
    for x in id_assignment_cells
), "No actual row_id assignment found."


assert any(
    x["duplicate_group_id_assignment"]
    for x in id_assignment_cells
), "No actual duplicate_group_id assignment found."


print(
    "✓ Actual assignment cells found:",
    len(id_assignment_cells)
)


# ============================================================
# 8. RESOLVE FUNCTION DEPENDENCIES
#
# Include user-defined functions called from assignment cells
# so normalization/hash helpers are preserved.
# ============================================================

function_def_cells = {}


for cell_index, src in code_cells:

    try:
        tree = ast.parse(
            src
        )
    except SyntaxError:
        continue


    for node in tree.body:

        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
            )
        ):

            function_def_cells[
                node.name
            ] = {
                "cell_index":
                    int(cell_index),

                "source":
                    src,
            }


called_functions = set()


for item in id_assignment_cells:

    try:
        tree = ast.parse(
            item["source"]
        )
    except SyntaxError:
        continue


    for node in ast.walk(
        tree
    ):

        if isinstance(
            node,
            ast.Call
        ):

            if isinstance(
                node.func,
                ast.Name
            ):

                called_functions.add(
                    node.func.id
                )


dependency_cells = {}


for name in called_functions:

    if name in function_def_cells:

        info = function_def_cells[
            name
        ]

        dependency_cells[
            info["cell_index"]
        ] = info[
            "source"
        ]


# Union exact source cells.
rowdup_cells = {
    item["cell_index"]:
        item["source"]
    for item in id_assignment_cells
}


rowdup_cells.update(
    dependency_cells
)


