def package_version(
    distribution,
    import_name=None
):

    try:
        return importlib.metadata.version(
            distribution
        )
    except Exception:
        pass

    if import_name:

        try:
            module = __import__(
                import_name
            )

            return getattr(
                module,
                "__version__",
                None
            )
        except Exception:
            pass

    return None


